## 4. TINYMCE: LOGO vs ICON INSERTION DIFFERENCES

### File: [renderers/tinymce/src/plugins/logos.ts](renderers/tinymce/src/plugins/logos.ts#L150-L180)

**Lines 150-180**: Logo insertion creates `<img>` with PNG rasterized width/height:

```ts
/**
 * Insert the selected logo into the editor as a real, hosted `<img>` — Canvas's RCE strips
 * inline `<svg>` and the CSS `background-image` this used to rely on, so the logo must be a
 * genuine raster image with its own `src`, `width`, and `height`.
 *
 * Silently no-ops if the product/layout/colorMode combination has no matching logo asset (e.g. not
 * every product ships every layout).
 */
export function insertLogo(
  editor: Editor,
  productId: string,
  layout: string,
  colorMode: string,
  buildAssetUrl: (file: CdnFile) => string = buildFileUrl,
): void {
  const meta = getLogoMeta(
    productId as Product,
    layout as LogoMeta["layout"],
    colorMode as LogoMeta["colorMode"],
  );
  if (!meta) return;

  const url = buildAssetUrl({
    package: "@pantoken/plugin-logos",
    path: `dist/${meta.name}.png`,
  });
  insertHtml(editor, generateLogoHtml(meta, url));
}

/**
 * Generate the `<img>` HTML for a resolved logo asset, sized from its rasterized PNG's `width`/
 * `height` metadata (see `@pantoken/plugin-logos`' `getLogoMeta`).
 */
export function generateLogoHtml(meta: LogoMeta, url: string): string {
  return `<img class="instui-img" src="${url}" width="${meta.width}" height="${meta.height}" alt="${meta.product} ${TINYMCE_STRINGS.logoAltSuffix}" />`;
}
```

**Why `<img>` for logos, not CSS class?**:
- Canvas LMS RCE (rich-text editor) **strips inline `<svg>` elements**
- Canvas RCE also **strips `background-image` CSS properties**
- **Only `<img src>` survives** Canvas's sanitization
- PNG is pre-rasterized at build time via `@resvg/resvg-js`, CDN-hosted

### File: [renderers/tinymce/src/plugins/icons.ts](renderers/tinymce/src/plugins/icons.ts#L1-L50)

**Lines 33-80**: Icon insertion creates `<span class="instui-icon -icon-{name}">`:

```ts
/** Insert an icon and make sure the editor's content area has the CSS to paint it. */
function insertIcon(editor: Editor, icon: TaggedIcon, options: IconsPickerOptions): void {
  insertHtml(editor, buildIconMarkup(icon));
  trackAndInjectAsset(editor, getIconCdnFile(icon), options);
}

function openIconsDialog(editor: Editor, options: IconsPickerOptions): void {
  let picker: { destroy: () => void; getSelected: () => TaggedIcon | undefined } | undefined;

  const dialog = editor.windowManager.open({
    title: TINYMCE_STRINGS.iconsDialogTitle,
    size: "large",
    // ... dialog body ...
    onSubmit: (api) => {
